create or replace function public.hr_admin_dashboard_summary(p_company_id uuid) returns jsonb language sql security definer set search_path=pg_catalog,public,hr as $$ select jsonb_build_object('employees',coalesce((select count(*) from hr.employees where company_id=p_company_id),0),'activeEmployees',coalesce((select count(*) from hr.employees where company_id=p_company_id and status='active'),0),'sponsoredEmployees',coalesce((select count(distinct employee_id) from hr.sponsor_cases where company_id=p_company_id and compliance_status<>'closed'),0),'onLeave',coalesce((select count(distinct employee_id) from hr.leave_requests where company_id=p_company_id and approval_status='approved' and current_date between starts_on and ends_on),0),'openCompliance',coalesce((select count(*) from hr.compliance_tasks where company_id=p_company_id and status in ('open','in_review')),0),'visaExpiring90Days',coalesce((select count(*) from hr.sponsor_cases where company_id=p_company_id and visa_expiry_date between current_date and current_date+90),0),'pendingPayroll',coalesce((select count(*) from hr.payroll_runs where company_id=p_company_id and status in ('draft','review_pending')),0),'liveSubmissionsEnabled',false) from hr.employers where company_id=p_company_id; $$;revoke all on function public.hr_admin_dashboard_summary(uuid) from public,anon,authenticated;grant execute on function public.hr_admin_dashboard_summary(uuid) to service_role;comment on function public.hr_admin_dashboard_summary(uuid) is 'Server-only HR summary. Caller must independently verify active Super Admin and company scope.';